{
  "items": [
    {
      "name": "Matrix.det_le",
      "module_name": "Mathlib.LinearAlgebra.Matrix.AbsoluteValue",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} {S : Type u_2} [inst : CommRing R] [Nontrivial R] [inst_2 : CommRing S] [inst_3 : LinearOrder S]\n  [IsStrictOrderedRing S] {n : Type u_3} [inst_5 : Fintype n] [inst_6 : DecidableEq n] {A : Matrix n n R}\n  {abv : AbsoluteValue R S} {x : S},\n  (∀ (i j : n), abv (A i j) ≤ x) → abv A.det ≤ (Fintype.card n).factorial • x ^ Fintype.card n"
    },
    {
      "name": "Matrix.det_sum_smul_le",
      "module_name": "Mathlib.LinearAlgebra.Matrix.AbsoluteValue",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} {S : Type u_2} [inst : CommRing R] [Nontrivial R] [inst_2 : CommRing S] [inst_3 : LinearOrder S]\n  [IsStrictOrderedRing S] {n : Type u_3} [inst_5 : Fintype n] [inst_6 : DecidableEq n] {ι : Type u_4} (s : Finset ι)\n  {c : ι → R} {A : ι → Matrix n n R} {abv : AbsoluteValue R S} {x : S},\n  (∀ (k : ι) (i j : n), abv (A k i j) ≤ x) →\n    ∀ {y : S},\n      (∀ (k : ι), abv (c k) ≤ y) →\n        abv (∑ k ∈ s, c k • A k).det ≤ (Fintype.card n).factorial • (s.card • y * x) ^ Fintype.card n"
    },
    {
      "name": "MvPowerSeries.coeff_eq_zero_of_lt_weightedOrder",
      "module_name": "Mathlib.RingTheory.MvPowerSeries.Order",
      "kind": "theorem",
      "type": "∀ {σ : Type u_1} {R : Type u_2} [inst : Semiring R] (w : σ → ℕ) {f : MvPowerSeries σ R} {d : σ →₀ ℕ},\n  ↑((Finsupp.weight w) d) < MvPowerSeries.weightedOrder w f → (MvPowerSeries.coeff d) f = 0"
    },
    {
      "name": "MvPowerSeries.coeff_mul_prod_one_sub_of_lt_weightedOrder",
      "module_name": "Mathlib.RingTheory.MvPowerSeries.Order",
      "kind": "theorem",
      "type": "∀ {σ : Type u_1} (w : σ → ℕ) {R : Type u_4} {ι : Type u_5} [inst : CommRing R] (d : σ →₀ ℕ) (s : Finset ι)\n  (f : MvPowerSeries σ R) (g : ι → MvPowerSeries σ R),\n  (∀ i ∈ s, ↑((Finsupp.weight w) d) < MvPowerSeries.weightedOrder w (g i)) →\n    (MvPowerSeries.coeff d) (f * ∏ i ∈ s, (1 - g i)) = (MvPowerSeries.coeff d) f"
    },
    {
      "name": "MvPowerSeries.nat_le_weightedOrder",
      "module_name": "Mathlib.RingTheory.MvPowerSeries.Order",
      "kind": "theorem",
      "type": "∀ {σ : Type u_1} {R : Type u_2} [inst : Semiring R] (w : σ → ℕ) {f : MvPowerSeries σ R} {n : ℕ},\n  (∀ (d : σ →₀ ℕ), (Finsupp.weight w) d < n → (MvPowerSeries.coeff d) f = 0) → ↑n ≤ MvPowerSeries.weightedOrder w f"
    }
  ]
}
